"""Random bracket strings, some genuinely balanced (built by nesting), some
deliberately broken in one of the three ways the problem describes."""


def generate(rng, count):
    builders = (_balanced, _unclosed, _unopened, _mismatched_type)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


PAIRS = [("(", ")"), ("[", "]"), ("{", "}")]


def _balanced_string(rng, depth):
    if depth <= 0 or rng.random() < 0.3:
        return "x" if rng.random() < 0.5 else ""
    open_, close_ = rng.choice(PAIRS)
    inner = _balanced_string(rng, depth - 1)
    return open_ + inner + close_ + _balanced_string(rng, depth - 1)


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _balanced(rng, index):
    text = _balanced_string(rng, rng.randint(1, 4))
    return _case("a balanced string, nested and interspersed with noise #%d"
                 % index, text)


def _unclosed(rng, index):
    text = _balanced_string(rng, rng.randint(1, 3))
    open_, _ = rng.choice(PAIRS)
    return _case("balanced, plus one trailing unclosed bracket #%d" % index,
                 text + open_,
                 "Nothing ever mismatches while scanning -- only the stack "
                 "being non-empty at the end catches this.")


def _unopened(rng, index):
    text = _balanced_string(rng, rng.randint(1, 3))
    _, close_ = rng.choice(PAIRS)
    return _case("a closing bracket with nothing open to match #%d" % index,
                 close_ + text)


def _mismatched_type(rng, index):
    (open_a, _), (_, close_b) = rng.sample(PAIRS, 2)
    return _case("an opening and closing bracket of different types #%d"
                 % index, open_a + close_b)
